import{_ as n,C as i,o,c as s,a2 as t,b as l,w as r,a as d,E as A,a3 as c}from"./chunks/framework.BODD28Fk.js";const g="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=",D=JSON.parse('{"title":"관리자 페이지 (Django Admin)","description":"","frontmatter":{},"headers":[],"relativePath":"authority/admin-page.md","filePath":"authority/admin-page.md","lastUpdated":1793458915000}'),E={name:"authority/admin-page.md"};function C(m,a,u,B,p,h){const e=i("Mermaid");return o(),s("div",null,[a[1]||(a[1]=t('<h1 id="관리자-페이지-django-admin" tabindex="-1">관리자 페이지 (Django Admin) <a class="header-anchor" href="#관리자-페이지-django-admin" aria-label="Permalink to &quot;관리자 페이지 (Django Admin)&quot;">​</a></h1><p>시스템의 로우 레벨 데이터 관리, 마스터 데이터 긴급 복구 및 프론트엔드에서 지원하지 않는 세부 시스템 설정을 수행하는 기술 관리자 전용 백오피스 도구입니다.</p><ul><li><strong>위치</strong>: <a href="https://ibs.dyibs.com/admin/" target="_blank" rel="noreferrer">ibs.dyibs.com/admin/</a> (스태프 권한 <code>is_staff</code> 계정 로그인 필요)</li></ul><div class="tip custom-block"><p class="custom-block-title">📸 실제 화면 안내</p><p><img src="'+g+'" alt="관리자 페이지 화면"><em>관리자 참고: 해당 화면의 실제 캡처 이미지를 <code>./images/admin-page.png</code> 경로에 등록해 주세요.</em></p></div><h2 id="개요" tabindex="-1">개요 <a class="header-anchor" href="#개요" aria-label="Permalink to &quot;개요&quot;">​</a></h2><p>프론트엔드(Vue SPA)가 정형화된 비즈니스 규칙과 업무 흐름에 따라 일반 사용자의 입력을 처리한다면, **관리자 페이지(Django Admin)**는 데이터베이스의 모델(Model)에 직접 접근하여 시스템의 근간 데이터를 제어하는 백오피스입니다. 데이터 정합성 오류 긴급 복구, 대량 데이터 일괄 관리, 시스템 관리자 권한 부여 등 &#39;시스템 마스터 컨트롤러&#39;의 역할을 수행합니다.</p>',6)),(o(),l(c,null,{default:r(()=>[A(e,{id:"mermaid-24",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%221.%20%EC%8A%A4%ED%83%9C%ED%94%84%20%EA%B3%84%EC%A0%95%20%EB%A1%9C%EA%B7%B8%EC%9D%B8%3Cbr%2F%3E(is_staff%20%EC%9D%B4%EC%83%81%20%EA%B6%8C%ED%95%9C)%22%5D%20--%3E%20B%5B%222.%20%EB%8D%B0%EC%9D%B4%ED%84%B0%20%EB%8F%84%EB%A9%94%EC%9D%B8%20%ED%83%90%EC%83%89%3Cbr%2F%3E(%EA%B3%84%EC%A0%95%C2%B7%ED%9A%8C%EC%82%AC%C2%B7%EA%B3%84%EC%95%BD%C2%B7%EC%9E%90%EA%B8%88%20%EB%93%B1)%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%223.%20%EB%A1%9C%EC%9A%B0%20%EB%A0%88%EB%B2%A8%20%EB%8D%B0%EC%9D%B4%ED%84%B0%20%EC%A0%9C%EC%96%B4%3Cbr%2F%3E(%EB%A7%88%EC%8A%A4%ED%84%B0%20%EB%B3%B5%EA%B5%AC%C2%B7%EC%A7%81%EC%A0%91%20%EC%88%98%EC%A0%95)%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%224.%20%EB%8C%80%EB%9F%89%20%EC%9D%BC%EA%B4%84%20%EC%95%A1%EC%85%98%3Cbr%2F%3E(Admin%20Action%20%EC%83%81%ED%83%9C%20%EB%B3%80%EA%B2%BD)%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%225.%20%EB%B3%80%EA%B2%BD%20%EA%B0%90%EC%82%AC%20%EB%A1%9C%EA%B7%B8%20%ED%99%95%EC%9D%B8%3Cbr%2F%3E(LogEntry%20%EC%B6%94%EC%A0%81)%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="주요-관리-기능" tabindex="-1">주요 관리 기능 <a class="header-anchor" href="#주요-관리-기능" aria-label="Permalink to &quot;주요 관리 기능&quot;">​</a></h2><ul><li><strong>데이터베이스 전수 관리</strong>: 데이터베이스에 정의된 모든 애플리케이션(App)과 테이블(Model)에 대한 직접적인 조회·생성·수정·삭제(CRUD) 지원</li><li><strong>사용자 및 시스템 권한 제어</strong>: 최상위 슈퍼유저 권한(<code>is_superuser</code>), 스태프 접속 권한(<code>is_staff</code>) 및 Django 모델 단위 기본 권한 부여</li><li><strong>마스터 데이터 긴급 복구</strong>: 프론트엔드 유효성 검사 오류로 꼬인 비즈니스 데이터나 일반 화면에서 삭제가 잠긴 비정상 레코드의 강제 수정 및 복원</li><li><strong>상세 감사 이력(Audit Log) 추적</strong>: 관리자 페이지를 통해 발생한 모든 데이터의 생성, 수정, 삭제 이력(<code>LogEntry</code>)을 담당자 및 시점별로 영구 보관</li><li><strong>대량 데이터 일괄 액션 (Admin Actions)</strong>: 목록에서 다수의 레코드를 선택한 후 원클릭으로 상태를 일괄 변경하거나 엑셀로 추출</li></ul><h2 id="도메인별-관리-범위" tabindex="-1">도메인별 관리 범위 <a class="header-anchor" href="#도메인별-관리-범위" aria-label="Permalink to &quot;도메인별 관리 범위&quot;">​</a></h2><p>관리자 페이지는 수많은 비즈니스 도메인을 체계적인 그룹으로 나누어 관리합니다.</p><h3 id="_1-계정-및-권한-accounts-auth" tabindex="-1">1. 계정 및 권한 (Accounts &amp; Auth) <a class="header-anchor" href="#_1-계정-및-권한-accounts-auth" aria-label="Permalink to &quot;1. 계정 및 권한 (Accounts &amp; Auth)&quot;">​</a></h3><ul><li><strong>사용자 (User)</strong>: 계정 생성, 비밀번호 강제 초기화, 슈퍼유저 및 스태프 권한 부여, 계정 활성화/비활성화</li><li><strong>프로필 (Profile)</strong>: 사용자별 부서, 직책, 연락처 등 상세 프로필 관리</li><li><strong>스태프 권한 (StaffAuth)</strong>: 프론트엔드 전용 기능별 세부 권한 플래그 설정</li></ul><h3 id="_2-회사-및-조직-company-organization" tabindex="-1">2. 회사 및 조직 (Company &amp; Organization) <a class="header-anchor" href="#_2-회사-및-조직-company-organization" aria-label="Permalink to &quot;2. 회사 및 조직 (Company &amp; Organization)&quot;">​</a></h3><ul><li><strong>회사 (Company)</strong>: 시스템 운영 주체 법인 정보 및 사업자 등록 데이터 관리</li><li><strong>회사 인장 (CompanySeal)</strong>: 법인인감, 사용인감, 부서/프로젝트 직인 이미지 및 전결 자격 기준 설정</li><li><strong>부서 및 직책 (Department, Duty, Position)</strong>: 회사 조직도 체계 및 직급/직책 마스터 데이터 관리</li></ul><h3 id="_3-프로젝트-및-비즈니스-코어-project-contract-payment-ledger" tabindex="-1">3. 프로젝트 및 비즈니스 코어 (Project, Contract, Payment, Ledger) <a class="header-anchor" href="#_3-프로젝트-및-비즈니스-코어-project-contract-payment-ledger" aria-label="Permalink to &quot;3. 프로젝트 및 비즈니스 코어 (Project, Contract, Payment, Ledger)&quot;">​</a></h3><ul><li><strong>프로젝트 (Project)</strong>: 프로젝트 생성, 사업지 상태 변경, 공용/비공개 설정</li><li><strong>계약 및 유닛 (Contract, HouseUnit, UnitType)</strong>: 분양 계약 상태 강제 복구, 동호수 매핑 교정</li><li><strong>수납 및 장부 (Payment, ProjectTransaction)</strong>: 은행 거래 전표, 수납 내역, 정산 일자 등 금융 회계 원장 관리</li></ul><h3 id="_4-업무-및-전자결재-work-approval-docs" tabindex="-1">4. 업무 및 전자결재 (Work, Approval, Docs) <a class="header-anchor" href="#_4-업무-및-전자결재-work-approval-docs" aria-label="Permalink to &quot;4. 업무 및 전자결재 (Work, Approval, Docs)&quot;">​</a></h3><ul><li><strong>업무 관리 (IssueProject, Issue, Meeting)</strong>: 워크스페이스 구조, 업무 이력, 회의록 마스터 관리</li><li><strong>전자결재 (Approval, Document)</strong>: 결재 양식 템플릿, 결재선 경로, 반려/승인 문서 복구</li><li><strong>문서 및 소송 (LawsuitCase, Docs)</strong>: 소송 사건 마스터, 법률 문서, 첨부 파일 링크 제어</li></ul><h2 id="💡-주요-관리-포인트-및-주의-사항" tabindex="-1">💡 주요 관리 포인트 및 주의 사항 <a class="header-anchor" href="#💡-주요-관리-포인트-및-주의-사항" aria-label="Permalink to &quot;💡 주요 관리 포인트 및 주의 사항&quot;">​</a></h2><div class="caution custom-block github-alert"><p class="custom-block-title">CAUTION</p><p><strong>직접 수정 시 비즈니스 로직 우회 위험</strong> 관리자 페이지에서의 데이터 직접 수정은 프론트엔드의 복잡한 유효성 검사, 시그널(Signal) 트리거, 자동 분개 로직을 우회할 수 있습니다. 특히 **수납(Payment)**이나 <strong>회계 자금(Ledger)</strong> 데이터를 임의로 수정하면 정산 장부의 차액 불일치가 발생하므로, 반드시 데이터 구조와 종속 관계를 완벽히 숙지한 시스템 관리자만 수행해야 합니다.</p></div><ul><li><strong>권한 체계의 이중 구조 이해</strong>: <ul><li>일반 업무 메뉴 노출은 프론트엔드의 <code>권한 설정 관리</code>에서 제어됩니다.</li><li>하지만 관리자 백오피스(<code>.../admin/</code>)에 로그인하려면 사용자 정보의 <strong>스태프 권한(<code>is_staff</code>)</strong> 속성이 반드시 <code>True</code>로 켜져 있어야 합니다.</li></ul></li><li><strong>외래키(ForeignKey) 고아 데이터(Orphan) 발생 방지</strong>: 프론트엔드에서 삭제가 차단된 상위 데이터(예: 계약자가 존재하는 동호수, 입출금 전표가 연결된 은행 계좌 등)를 관리자 페이지에서 강제로 삭제할 경우 연관 하위 데이터들이 유실되거나 시스템 오류를 일으킬 수 있습니다. 삭제 전 반드시 연관 관계를 확인하십시오.</li><li><strong>초기 대량 데이터 세팅 편의성</strong>: 신규 프로젝트 개설 시 수백 개의 동호수 정보나 기초 비목 정보를 밀어넣어야 할 때, 관리자 페이지의 대량 입력 또는 스크립트 실행 기능을 활용하면 빠르고 정확하게 기초 데이터를 구축할 수 있습니다.</li></ul>',15))])}const b=n(E,[["render",C]]);export{D as __pageData,b as default};
